export class Product {
  public constructor(
    public readonly id: string,
    public readonly name: string,
    private availableStock: number,
  ) {
    if (!id.trim()) throw new Error("Product id is required");
    if (!name.trim()) throw new Error("Product name is required");
    if (!Number.isInteger(availableStock) || availableStock < 0) throw new Error("Stock must be a non-negative integer");
  }

  public get stock(): number {
    return this.availableStock;
  }

  public reserve(quantity: number): void {
    this.assertQuantity(quantity);
    if (this.availableStock < quantity) throw new Error("Insufficient stock");
    this.availableStock -= quantity;
  }

  public release(quantity: number): void {
    this.assertQuantity(quantity);
    this.availableStock += quantity;
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity <= 0) throw new Error("Quantity must be a positive integer");
  }
}

=====SOURCE-END=====

